{
  "application": "data-visualization",
  "case_id": "case-car-selection-parallel-coordinates",
  "language": "en",
  "style": {
    "theme": "business",
    "audience": "general public",
    "tone": "informative, accessible, consumer-oriented"
  },
  "goal": [
    {
      "id": "no-all-rounder",
      "insight": "Show via parallel coordinates that every car excels in some dimensions but drops in others, making visible the absence of any single model dominating all seven axes simultaneously"
    },
    {
      "id": "seven-dim-encoding",
      "insight": "Encode seven parallel axes (price, fuel efficiency, power, safety, interior space, resale value, emission rating) with polylines colored by vehicle type: SUV, sedan, and electric"
    },
    {
      "id": "type-clustering-bands",
      "insight": "Emphasize how each vehicle type (SUV, sedan, electric) forms distinct band patterns across certain axes — e.g., SUVs cluster high on space but low on fuel efficiency, electrics cluster high on emissions but vary widely on price"
    },
    {
      "id": "tradeoff-crossings",
      "insight": "Highlight the frequent line crossings between the power and fuel-efficiency axes, showing a prominent trade-off pattern, and note the varied crossings between price and resale-value axes, where brand reliability and demand create unpredictable relationships"
    },
    {
      "id": "top-performers-per-axis",
      "insight": "Visually distinguish the top-ranked car on each individual axis so viewers can see that different models lead on different dimensions"
    }
  ]
}

